import{_ as t}from"./chunks/1model_search.BWUAcQSN.js";import{_ as a,c as n,o as r,ag as o}from"./chunks/framework.Bzez9NG9.js";const s="/space/img/ms_save-replace.png",f=JSON.parse('{"title":"Model search","description":"Search across IBM Planning Analytics and TM1 model objects, inspect matching rules and TurboIntegrator code, perform search and replace, and quickly locate where model logic is implemented.","frontmatter":{"title":"Model search","description":"Search across IBM Planning Analytics and TM1 model objects, inspect matching rules and TurboIntegrator code, perform search and replace, and quickly locate where model logic is implemented.","keywords":["IBM Planning Analytics","Planning Analytics","TM1","model search","search TM1 code","TurboIntegrator","TI processes","rules","Prolog","Metadata","Data","Epilog","find and replace","impact analysis"],"outline":"deep"},"headers":[],"relativePath":"doc/planning-analytics/model-search.md","filePath":"doc/planning-analytics/model-search.md"}'),c={name:"doc/planning-analytics/model-search.md"};function l(i,e,d,h,p,m){return r(),n("div",null,e[0]||(e[0]=[o('<h1 id="model-search" tabindex="-1">Model search <a class="header-anchor" href="#model-search" aria-label="Permalink to &quot;Model search&quot;">​</a></h1><p><strong>Model search</strong> lets you search across IBM Planning Analytics model objects from one place. Use it to find text, object references, element names, or code across TM1 processes, rules, cubes, chores, and other supported objects without opening them individually.</p><p>It is useful for understanding unfamiliar models, locating where logic is implemented, tracing references before making a change, and finding code that needs to be updated across multiple objects.</p><p><img src="'+t+'" alt="Model search UI" data-zoomable=""></p><h2 id="searching-the-model" tabindex="-1">Searching the model <a class="header-anchor" href="#searching-the-model" aria-label="Permalink to &quot;Searching the model&quot;">​</a></h2><p>Select a Planning Analytics connection and the object type you want to search, then enter a keyword, object name, element name, or code fragment.</p><p>SPACE searches its indexed model content so matching objects can be returned quickly.</p><ul><li><strong>Search bar</strong> — enter the text or code you want to find. Results update as you type.</li><li><strong>Object type</strong> — focus the search on processes, chores, cubes, rules, or another supported object type.</li><li><strong>System objects</strong> — include or exclude TM1 system objects from the results.</li><li><strong>Refresh</strong> — retrieve the latest model content when changes have been made on the selected Planning Analytics environment.</li></ul><p>For example, you can search for a cube name to find processes or rules that reference it, search for an element or variable used in TI code, or locate a particular function or code fragment across the model.</p><h2 id="inspecting-results" tabindex="-1">Inspecting results <a class="header-anchor" href="#inspecting-results" aria-label="Permalink to &quot;Inspecting results&quot;">​</a></h2><p>Select an object from the results to inspect the matching content directly in SPACE.</p><p>For TurboIntegrator processes, tabs such as <strong>Prolog</strong>, <strong>Metadata</strong>, <strong>Data</strong>, and <strong>Epilog</strong> make it easy to see which section contains the match.</p><p>Matching text is highlighted, and you can move between occurrences using <strong>Next</strong> or the keyboard shortcuts:</p><ul><li><code>Ctrl/Cmd + G</code> — next match</li><li><code>Shift + Ctrl/Cmd + G</code> — previous match</li></ul><p>This makes Model search useful not only for finding an object, but also for quickly understanding where and how a reference is used.</p><h2 id="search-and-replace" tabindex="-1">Search and replace <a class="header-anchor" href="#search-and-replace" aria-label="Permalink to &quot;Search and replace&quot;">​</a></h2><p>Use <strong>Search and replace</strong> when the same text or code needs to be changed across multiple objects.</p><p><img src="'+s+'" alt="Search and replace flow" data-zoomable=""></p><ol><li>Open the three-dot menu and select <strong>Search and replace</strong>.</li><li>Enter the text to find and the replacement text.</li><li>Review the search scope.</li><li>Select <strong>Replace all</strong> to replace matching instances within the selected object type on the selected Planning Analytics environment.</li></ol><p>Search and replace is useful for coordinated model changes where the same reference appears in multiple objects. Review the intended scope carefully before applying a replacement, particularly in shared or production environments.</p><h2 id="refreshing-model-search" tabindex="-1">Refreshing model search <a class="header-anchor" href="#refreshing-model-search" aria-label="Permalink to &quot;Refreshing model search&quot;">​</a></h2><p>Model search uses indexed model content to provide fast results. When model objects have changed, refresh the indexed content so searches reflect the latest version of the Planning Analytics environment.</p><p>Use <strong>Refresh cache</strong> from the menu when the search index needs to be rebuilt, such as after a significant deployment or set of model changes.</p><p>Only administrators can run <strong>Refresh cache</strong>.</p>',24)]))}const b=a(c,[["render",l]]);export{f as __pageData,b as default};
